/*
 * A347433  Irregular triangle read by rows: T(n,k) is the difference between
 *          the total arch lengths of a semi-meander multiplied by its number
 *          of exterior arches and total arch lengths of the semi-meanders
 *          with n + 1 top arches generated by the exterior arch splitting
 *          algorithm on the given semi-meander.
 * https://oeis.org/A347433
 *
 * Offset:    2    (a(2) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   T(n,k) = 4 + (n+2)*(k-2) (n >= 2, 2 <= k <= floor((n+2)/2)) a(n)
 *            is the sequence obtained by reading this triangle row by row,
 *            starting with n = 2 (offset = 2)
 * Range:     u8 n <= 71, u16 n <= 71, u32 n <= 71, u64 n <= 71, u128 n <= 71,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <math.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    /* Ignore indices below the offset – behaviour is undefined */
    if (n < 2)
        return (seq_t)0;

    /* 1‑based index into the infinite sequence */
    idx_t idx = n - 1;

    /* Integer square‑root of idx */
    idx_t m = (idx_t)sqrtl((long double)idx);
    while ((unsigned __int128)(m + 1) * (m + 1) <= idx)
        ++m;
    while ((unsigned __int128)m * m > idx)
        --m;

    /* Determine the row r (triangle index) */
    idx_t r;
    if (idx <= m * m)
        r = 2 * m;               /* even row */
    else if (idx <= m * (m + 1))
        r = 2 * m + 1;           /* odd row */
    else
        r = 2 * (m + 1);         /* even row */

    /* Position within the row (1‑based) */
    idx_t pos;
    if ((r & 1) == 0) {          /* r even */
        idx_t me = r / 2;
        pos = idx - (me - 1) * me;
    } else {                     /* r odd */
        idx_t mo = (r - 1) / 2;
        pos = idx - mo * mo;
    }

    /* Compute the triangle entry T(r, pos+1) = 4 + (r+2)*(pos-1) */
    return (seq_t)(4 + (seq_t)(r + 2) * (pos - 1));
}
